function exercisesByCategory(category) {
  return EXERCISE_TEMPLATES.filter(e => e.category === category);
}

function findExercise(id) {
  return EXERCISE_TEMPLATES.find(e => e.id === id) || null;
}

module.exports = { EXERCISE_TEMPLATES, exercisesByCategory, findExercise };
